10|int LLVMFuzzerTestOneInput(const uint8_t *data, size_t dataLen) {
11|  uint32_t crc0 = crc32(0L, NULL, 0);
12|  uint32_t crc1 = crc0;
13|  uint32_t crc2 = crc0;
14|  uint32_t adler0 = adler32(0L, NULL, 0);
15|  uint32_t adler1 = adler0;
16|  uint32_t adler2 = adler0;
17|  /* Checksum with a buffer of size equal to the first byte in the input. */
18|  uint32_t buffSize = data[0];
19|  uint32_t offset = 0;
20|  z_crc_t op[32];
21|
22|  /* Discard inputs larger than 1Mb. */
23|  static size_t kMaxSize = 1024 * 1024;
24|  if (dataLen < 1 || dataLen > kMaxSize)
25|    return 0;
26|
27|  /* Make sure the buffer has at least a byte. */
28|  if (buffSize == 0)
29|    ++buffSize;
30|
31|  /* CRC32 */
32|  crc32_combine_gen(op, buffSize);
33|  for (offset = 0; offset + buffSize <= dataLen; offset += buffSize) {
34|    uint32_t crc3 = crc32_z(crc0, data + offset, buffSize);
35|    uint32_t crc4 = crc32_combine_op(crc1, crc3, op);
36|    crc1 = crc32_z(crc1, data + offset, buffSize);
37|    assert(crc1 == crc4);
38|  }
39|  crc1 = crc32_z(crc1, data + offset, dataLen % buffSize);
40|
41|  crc2 = crc32(crc2, data, (uint32_t) dataLen);
42|
43|  assert(crc1 == crc2);
44|  assert(crc32_combine(crc1, crc2, dataLen) ==
45|         crc32_combine(crc1, crc1, dataLen));
46|
47|  /* Fast CRC32 combine. */
48|  crc32_combine_gen(op, dataLen);
49|  assert(crc32_combine_op(crc1, crc2, op) ==
50|         crc32_combine_op(crc2, crc1, op));
51|  assert(crc32_combine(crc1, crc2, dataLen) ==
52|         crc32_combine_op(crc2, crc1, op));
53|
54|  /* Adler32 */
55|  for (offset = 0; offset + buffSize <= dataLen; offset += buffSize)
56|    adler1 = adler32_z(adler1, data + offset, buffSize);
57|  adler1 = adler32_z(adler1, data + offset, dataLen % buffSize);
58|
59|  adler2 = adler32(adler2, data, (uint32_t) dataLen);
60|
61|  assert(adler1 == adler2);
62|  assert(adler32_combine(adler1, adler2, dataLen) ==
63|         adler32_combine(adler1, adler1, dataLen));
64|
65|  /* This function must return 0. */
66|  return 0;
67|}

